import {ACCOUNT_ID} from './poller.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={boost:'一键起量',heat:'素材追投',search:'搜索抢首屏'};
async function post(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),j=await r.json();if(!r.ok)throw new Error(j.error?.message||'请求失败');return j;}
export function openTaskForm(plan,{kind='boost',notify,onSuccess,allowWrites=false}){
 const dialog=document.createElement('dialog');dialog.className='operation-dialog task-dialog';dialog.setAttribute('aria-label','新建调控任务');
 let selected=new Set(),page=1,prepared=null,working=false;
 const d=new Date(),parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(d).map(p=>[p.type,p.value]));
 const date=`${parts.year}-${parts.month}-${parts.day}`,dateStamp=date.replace(/-/g,''),clock=`${parts.hour}:${parts.minute}:${parts.second}`;
 const start=new Date(date+'T00:00:00Z');start.setUTCDate(start.getUTCDate()-7);const from=start.toISOString().slice(0,10);
 dialog.innerHTML=`<header><h2>新建调控任务</h2><button data-close aria-label="关闭调控表单">×</button></header><p>${esc(plan.name)}<br>ID：${esc(plan.id)}</p><label>调控工具<select id="task-kind">${Object.entries(names).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><div id="task-fields"></div><p class="operation-error" role="alert"></p><footer><button data-close>取消</button><button class="primary" id="prepare-task">核对任务</button></footer>`;
 if(!allowWrites){dialog.querySelector('h2').textContent='调控任务表单（只读预览）';dialog.querySelector('header').insertAdjacentHTML('afterend','<p class="readonly-notice">仅核对字段与规则，不会创建任务或使用预算。</p>');}
 document.body.append(dialog);dialog.showModal();const $=s=>dialog.querySelector(s);$('#task-kind').value=kind;
 function render(){prepared=null;selected.clear();$('#prepare-task').disabled=false;$('#prepare-task').textContent='核对任务';$('#task-fields').innerHTML=`${kind==='heat'?'<button type="button" id="select-videos">添加视频</button><span id="video-count"> 已选0/20</span><div id="video-list"></div>':''}<label>调控预算（元）<input id="task-budget" inputmode="decimal" placeholder="请输入"></label><small>额外独立预算，至少100元且不超过主计划预算${esc(plan.budget)}元。</small>${kind==='search'?'<label>综合营销ROI目标<input id="task-roi" inputmode="decimal" placeholder="0.01–100，最多两位小数"></label>':'<label>调控时长（小时）<input id="task-duration" type="number" min="0.5" max="24" step="0.5" placeholder="0.5–24"></label><small>时长必须为0.5小时的整数倍；调控任务不支持成本保障。</small>'}<label>任务名称<input id="task-name" value="${dateStamp}_${names[kind]}_${clock}" maxlength="100"></label>`;if(kind==='heat')$('#select-videos').onclick=()=>void loadVideos();}
 async function loadVideos(){try{$('.operation-error').textContent='正在查询可追投素材…';const data=await post('/api/detail',{accountId:ACCOUNT_ID,id:plan.id,tab:'material',materialType:'video',eligible:true,from,to:date,page,pageSize:10});$('#video-list').innerHTML=`<p>仅允许选择原页返回可追投的视频</p>${data.rows.map(r=>`<label class="task-video"><input type="checkbox" data-video="${esc(r.id)}" ${selected.has(r.id)?'checked':''} ${r.canHeat?'':'disabled'}><span>${esc(r.name)}<small>ID：${esc(r.id)} ${r.canHeat?'':esc(r.reason)}</small></span></label>`).join('')||'<p>当前计划暂无可追投视频</p>'}<button type="button" data-video-page="${page-1}" ${page<=1?'disabled':''}>上一页</button> ${page} / ${Math.max(1,Math.ceil(data.total/10))} <button type="button" data-video-page="${page+1}" ${page>=Math.ceil(data.total/10)?'disabled':''}>下一页</button>`;$('.operation-error').textContent='';}catch(e){$('.operation-error').textContent=e.message;}}
 $('#task-kind').onchange=()=>{kind=$('#task-kind').value;page=1;render();};
 dialog.addEventListener('change',e=>{if(e.target.dataset.video){if(e.target.checked&&selected.size>=20){e.target.checked=false;notify('最多选择20个视频');return;}e.target.checked?selected.add(e.target.dataset.video):selected.delete(e.target.dataset.video);$('#video-count').textContent=' 已选'+selected.size+'/20';}});
 dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close')&&!working)dialog.close();if(b.dataset.videoPage){page=Number(b.dataset.videoPage);void loadVideos();}});
 $('#prepare-task').onclick=async()=>{if(working)return;working=true;$('#prepare-task').disabled=true;try{
  if(!prepared){prepared=await post('/api/operation/prepare',{accountId:ACCOUNT_ID,id:plan.id,action:'task',value:{kind,name:$('#task-name').value,budget:$('#task-budget').value,duration:$('#task-duration')?.value,roi:$('#task-roi')?.value,materialIds:[...selected]}});$('#task-fields').innerHTML=`<p class="confirmation-summary">${esc(prepared.description)}</p><p>${prepared.canSubmit?'确认后会在真实账户创建任务并使用额外预算。':'当前为只读模式，任务仅预览，未向千川提交。'}</p>`;$('#task-kind').disabled=true;$('#prepare-task').textContent=prepared.canSubmit?'确认创建任务':'只读预览，未提交';}
  else {const r=await post('/api/operation/commit',{token:prepared.token,accountId:ACCOUNT_ID,planId:plan.id,confirmed:true});if(r.success){notify('平台已确认创建成功');dialog.close();onSuccess();}}
 }catch(e){$('.operation-error').textContent=e.message;if(prepared){$('#prepare-task').dataset.failed='true';$('#prepare-task').textContent='请查看原页或日志后再操作';}}finally{working=false;$('#prepare-task').disabled=prepared?.canSubmit===false||$('#prepare-task').dataset.failed==='true';}};
 dialog.addEventListener('cancel',e=>{if(working)e.preventDefault();});dialog.addEventListener('close',()=>dialog.remove());render();
}
